import {motions,groups} from './motions.js';
import {drawMotion} from './render.js';
const $=id=>document.getElementById(id);
const escape=s=>String(s).replace(/[&<>"']/g,x=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[x]));
let saved=new Set();try{saved=new Set(JSON.parse(localStorage.getItem('balarab-motion-picks')||'[]'));}catch{}
const state={category:'all',query:'',savedOnly:false,playing:!matchMedia('(prefers-reduced-motion: reduce)').matches,detail:null,detailPlaying:false,detailTime:0};
let contexts=[],lastPaint=0,toastTimeout=null,opener=null;
const visible=new Set();
const observer=new IntersectionObserver(items=>items.forEach(item=>item.isIntersecting?visible.add(item.target):visible.delete(item.target)),{rootMargin:'70px'});
function toast(message){$('toast').textContent=message;$('toast').classList.add('visible');clearTimeout(toastTimeout);toastTimeout=setTimeout(()=>$('toast').classList.remove('visible'),2400);}
async function copy(value){try{await navigator.clipboard.writeText(value);toast('تم النسخ');}catch{const field=document.createElement('textarea');field.value=value;document.body.append(field);field.select();const ok=document.execCommand('copy');field.remove();toast(ok?'تم النسخ':'تعذر النسخ؛ افتح الحركة وانسخ اسمها ورقمها.');}}
function persist(){try{localStorage.setItem('balarab-motion-picks',JSON.stringify(Array.from(saved)));}catch{}$('saved-count').textContent=saved.size;}
function save(id){saved.has(id)?saved.delete(id):saved.add(id);persist();for(const button of document.querySelectorAll('[data-save="'+id+'"]')){button.classList.toggle('selected',saved.has(id));button.textContent=saved.has(id)?'★':'☆';button.setAttribute('aria-pressed',String(saved.has(id)));}if(state.detail?.id===id)$('save-detail').textContent=saved.has(id)?'إزالة من المختارات':'أضف للمختارات';if(state.savedOnly)renderCards();}
function setFilters(){const filters=[['all','كل الحركات',motions.length]].concat(groups.map(g=>[g[0],g[1],g[4].length]));$('filters').innerHTML=filters.map(g=>'<button class="filter '+(state.category===g[0]?'active':'')+'" data-category="'+g[0]+'" aria-pressed="'+(state.category===g[0])+'">'+g[1]+'<span class="num">'+g[2]+'</span></button>').join('');}
function renderCards(){observer.disconnect();visible.clear();let items=motions.filter(m=>(state.category==='all'||m.category===state.category)&&(!state.savedOnly||saved.has(m.id))&&(!state.query||(m.id+' '+m.keywords).toLowerCase().includes(state.query.toLowerCase())));if($('sort').value==='name')items.sort((a,b)=>a.name.localeCompare(b.name,'ar'));$('cards').innerHTML=items.map(m=>'<article class="card"><button class="preview-button" data-open="'+m.id+'" aria-label="شاهد '+m.id+' '+escape(m.name)+'"><canvas width="640" height="420" data-motion="'+m.id+'" aria-label="معاينة '+escape(m.name)+'"></canvas><span class="card-marker">'+m.id+'</span><span class="expand" aria-hidden="true">↗</span></button><div class="card-body"><div class="card-top"><h3>'+escape(m.name)+'</h3><button class="save '+(saved.has(m.id)?'selected':'')+'" data-save="'+m.id+'" aria-pressed="'+saved.has(m.id)+'" aria-label="اختيار '+escape(m.name)+'">'+(saved.has(m.id)?'★':'☆')+'</button></div><p class="card-english" lang="en">'+escape(m.english)+'</p><p class="card-desc">'+escape(m.description)+'</p><div class="card-footer"><span class="pill">'+m.categoryName+'</span><button data-open="'+m.id+'">شاهد واطلب ↗</button></div></div></article>').join('');$('empty').hidden=!!items.length;$('results').textContent=items.length+' حركة'+(state.savedOnly?' من مختاراتك':' من أصل '+motions.length);contexts=Array.from(document.querySelectorAll('[data-motion]')).map(canvas=>({canvas,context:canvas.getContext('2d'),motion:motions.find(m=>m.id===canvas.dataset.motion)}));for(const item of contexts){drawMotion(item.context,item.motion,state.playing?.65:item.motion.duration*.82);observer.observe(item.canvas);}setFilters();$('show-saved').classList.toggle('primary',state.savedOnly);}
const usage={text:'اختر العبارة الأساسية ثم اربط الحركة بالكلمات المنطوقة. الهوك يظل كاملًا من أول فريم.',numbers:'اربط القيمة بعنصرها، وصرّح أن الأرقام مثال إذا كانت افتراضية. اترك النتيجة مستقرة للقراءة.',compare:'احتفظ بالطرفين وبياناتهما أثناء المقارنة، وانقل التركيز مع شرح كل طرف.',ui:'نفّذ المدخل والفعل والنتيجة داخل واجهة موبايل RTL، مع Click عند الضغط الفعلي.',flow:'حدد المصدر والفعل والوجهة والنتيجة. حافظ على نفس المنتج والطلب عبر الرحلة.',layout:'افسح مكانًا قبل دخول العنصر الجديد، وافحص الحدود وقت التكبير والاستقرار.',charts:'استخدم بيانات موثقة أو مثالًا معلنًا. حافظ على وحدة المحور واتجاه الزمن.',product:'اختر حركة تكشف خاصية المنتج، مع أصل متقن ونسب صحيحة واستقرار واضح.',transition:'اربط آخر حالة بأول حالة في المقطع التالي، واحفظ العنصر الذي يصل القصة.',emphasis:'ضع التأكيد بعد الفعل، واختر إشارة مرتبطة بالمعنى ومؤثرًا خفيفًا مناسبًا.'};
function openMotion(id,writeHash=true){const motion=motions.find(m=>m.id===id);if(!motion)return;opener=document.activeElement;state.detail=motion;state.detailTime=0;state.detailPlaying=true;$('detail-id').textContent=motion.id+' / '+motion.english;$('detail-title').textContent=motion.name;$('detail-category').textContent=motion.categoryName;$('detail-english').textContent=motion.english;$('detail-description').textContent=motion.description;$('detail-usage').textContent=motion.usage||usage[motion.category]||usage.flow;$('detail-source').textContent=(motion.referenceTitle||motion.source)+' — الكود ↗';$('detail-source').href=motion.referenceUrl;$('detail-example').hidden=!motion.exampleUrl;if(motion.exampleUrl)$('detail-example').href=motion.exampleUrl;$('detail-video').hidden=!motion.exampleVideoUrl;if(motion.exampleVideoUrl)$('detail-video').href=motion.exampleVideoUrl;$('reference-note').textContent=motion.referenceNote||'معاينة أصلية لبالعرب؛ الرابط مرجع تقني عام، وليس مصدر حركة منسوخة.';$('save-detail').textContent=saved.has(motion.id)?'إزالة من المختارات':'أضف للمختارات';$('scrub').max=Math.round(motion.duration*100);$('scrub').value=0;$('time').textContent='0.0 / '+motion.duration.toFixed(1);$('detail-play').textContent='Ⅱ';$('detail-play').setAttribute('aria-label','إيقاف الحركة');if(!$('detail').open)$('detail').showModal();if(writeHash)history.replaceState(null,'','#motion='+id);drawMotion(detailContext,motion,0);}
const heroContext=$('hero-canvas').getContext('2d'),detailContext=$('detail-canvas').getContext('2d');
function tick(ms){if(ms-lastPaint>32&&!document.hidden){const delta=lastPaint?Math.min(.12,(ms-lastPaint)/1000):0;lastPaint=ms;if(state.playing){const t=ms/1000;drawMotion(heroContext,motions[12],t);for(const item of contexts)if(visible.has(item.canvas))drawMotion(item.context,item.motion,t);}if(state.detail&&$('detail').open){if(state.detailPlaying)state.detailTime=(state.detailTime+delta)%state.detail.duration;drawMotion(detailContext,state.detail,state.detailTime);$('scrub').value=Math.round(state.detailTime*100);$('time').textContent=state.detailTime.toFixed(1)+' / '+state.detail.duration.toFixed(1);}}requestAnimationFrame(tick);}
$('filters').addEventListener('click',event=>{const button=event.target.closest('[data-category]');if(!button)return;state.category=button.dataset.category;renderCards();});
$('cards').addEventListener('click',event=>{const s=event.target.closest('[data-save]');if(s){save(s.dataset.save);return;}const o=event.target.closest('[data-open]');if(o)openMotion(o.dataset.open);});
$('search').addEventListener('input',()=>{state.query=$('search').value.trim();renderCards();});$('sort').addEventListener('change',renderCards);
$('reset').addEventListener('click',()=>{state.category='all';state.query='';state.savedOnly=false;$('search').value='';renderCards();});
$('show-saved').addEventListener('click',()=>{state.savedOnly=!state.savedOnly;state.category='all';renderCards();$('gallery').scrollIntoView({behavior:'smooth'});});
$('play-all').addEventListener('click',()=>{state.playing=!state.playing;$('play-all').textContent=state.playing?'إيقاف المعاينات':'تشغيل المعاينات';$('play-all').setAttribute('aria-pressed',String(state.playing));if(!state.playing)for(const item of contexts)if(visible.has(item.canvas))drawMotion(item.context,item.motion,item.motion.duration*.82);});
$('hero-open').addEventListener('click',()=>openMotion('M013'));$('close-detail').addEventListener('click',()=>$('detail').close());
$('detail').addEventListener('close',()=>{state.detailPlaying=false;state.detail=null;if(location.hash.startsWith('#motion='))history.replaceState(null,'','#gallery');opener?.focus();});
$('detail').addEventListener('click',event=>{if(event.target===$('detail')){const rect=$('detail').getBoundingClientRect();if(event.clientX<rect.left||event.clientX>rect.right||event.clientY<rect.top||event.clientY>rect.bottom)$('detail').close();}});
$('detail-play').addEventListener('click',()=>{state.detailPlaying=!state.detailPlaying;$('detail-play').textContent=state.detailPlaying?'Ⅱ':'▷';$('detail-play').setAttribute('aria-label',state.detailPlaying?'إيقاف الحركة':'تشغيل الحركة');});
$('scrub').addEventListener('input',()=>{state.detailPlaying=false;state.detailTime=Math.min(Number($('scrub').value)/100,state.detail.duration-.001);$('detail-play').textContent='▷';$('detail-play').setAttribute('aria-label','تشغيل الحركة');});
$('restart').addEventListener('click',()=>{state.detailTime=0;state.detailPlaying=true;$('detail-play').textContent='Ⅱ';$('detail-play').setAttribute('aria-label','إيقاف الحركة');});
const requestText=m=>'استخدم '+m.id+' — '+m.name+' ('+m.english+') في فقرة الفيديو التي يناسبها هذا الفعل: '+m.description+' اربط التوقيت بالمنطوق الفعلي وهوية بالعرب. '+location.origin+location.pathname+'#motion='+m.id;
$('copy-request').addEventListener('click',()=>copy(requestText(state.detail)));$('copy-link').addEventListener('click',()=>copy(location.origin+location.pathname+'#motion='+state.detail.id));$('save-detail').addEventListener('click',()=>save(state.detail.id));
$('share-picks').addEventListener('click',()=>{const items=motions.filter(m=>saved.has(m.id));if(!items.length){toast('اختر حركة أولًا باستخدام النجمة');return;}copy('مختارات موشن بالعرب\n'+items.map(m=>m.id+' — '+m.name+' ('+m.english+')').join('\n')+'\n'+location.origin+location.pathname+'#selected='+items.map(m=>m.id).join(','));});
document.addEventListener('keydown',event=>{if(event.key==='/'&&!/INPUT|TEXTAREA|SELECT/.test(document.activeElement.tagName)&&!$('detail').open){event.preventDefault();$('search').focus();}});
function readHash(){if(location.hash.startsWith('#motion=')&&state.detail?.id!==location.hash.slice(8))openMotion(location.hash.slice(8),false);if(location.hash.startsWith('#selected=')){const ids=location.hash.slice(10).split(',').filter(id=>motions.some(m=>m.id===id));ids.forEach(id=>saved.add(id));state.savedOnly=true;persist();renderCards();$('gallery').scrollIntoView();}}
await document.fonts.ready;persist();renderCards();drawMotion(heroContext,motions[12],state.playing?.65:4.2);$('play-all').textContent=state.playing?'إيقاف المعاينات':'تشغيل المعاينات';$('play-all').setAttribute('aria-pressed',String(state.playing));readHash();window.addEventListener('hashchange',readHash);requestAnimationFrame(tick);
try{const sources=await fetch('sources.json').then(r=>{if(!r.ok)throw new Error('sources unavailable');return r.json();});$('source-list').innerHTML=sources.entries.map(s=>'<article class="source-row"><div><a href="'+escape(s.source_url)+'" target="_blank" rel="noopener">'+escape(s.name)+' ↗</a><p>'+escape(s.description_ar)+'</p></div><div><a href="'+escape(s.license_url)+'" target="_blank" rel="noopener">'+escape(s.license)+'</a><span>'+s.stars.toLocaleString('en-US')+' نجمة'+(s.forks==null?'':' / '+s.forks.toLocaleString('en-US')+' Forks')+'</span><p>'+escape(s.arabic_adaptation_ar)+'</p></div></article>').join('');}catch{$('source-list').textContent='تعذر تحميل المصادر. أعد تحميل الصفحة.';}
window.motionGallery={total:motions.length,groups:groups.length,current:()=>state.detail?.id??null};
